import json, sys
from functools import lru_cache


def solve(request):
    mem0 = tuple(request["memory"])
    threads = request["threads"]
    T = len(threads)

    ins = []          # per-thread tuple of parsed instructions
    stores = []       # per-thread tuple of (addr, width, value) in program order
    issued_prefix = []  # per-thread prefix counts of store instructions
    for t in threads:
        its = []
        st = []
        for x in t:
            op = x[0]
            if op == "store":
                its.append(("store", x[1], x[2], x[3]))
                st.append((x[1], x[2], x[3]))
            elif op == "load":
                its.append(("load", x[1], x[2]))
            elif op == "fence":
                its.append(("fence",))
            elif op == "xchg":
                its.append(("xchg", x[1], x[2], x[3]))
            else:
                raise ValueError("bad instruction")
        ins.append(tuple(its))
        stores.append(tuple(st))
        pref = [0]
        c = 0
        for j in range(len(its)):
            if its[j][0] == "store":
                c += 1
            pref.append(c)
        issued_prefix.append(tuple(pref))

    L = tuple(len(x) for x in ins)
    empty_obs = tuple(() for _ in range(T))

    def write_bytes(mem, addr, width, value):
        m = list(mem)
        for b in range(width):
            m[addr + b] = (value >> (8 * b)) & 0xFF
        return tuple(m)

    def load_value(mem, addr, width, buf):
        out = 0
        for b in range(width):
            a = addr + b
            byte = None
            for s in reversed(buf):
                if s[0] <= a < s[0] + s[1]:
                    byte = (s[2] >> (8 * (a - s[0]))) & 0xFF
                    break
            if byte is None:
                byte = mem[a]
            out |= byte << (8 * b)
        return out

    @lru_cache(maxsize=None)
    def f(pcs, drains, mem):
        # terminal?
        done = True
        for i in range(T):
            if pcs[i] != L[i] or drains[i] != issued_prefix[i][pcs[i]]:
                done = False
                break
        if done:
            return frozenset(((empty_obs, mem),))

        results = set()

        # instruction transitions
        for i in range(T):
            pc = pcs[i]
            if pc >= L[i]:
                continue
            instr = ins[i][pc]
            op = instr[0]
            if op == "store":
                npcs = list(pcs)
                npcs[i] = pc + 1
                results.update(f(tuple(npcs), drains, mem))
            elif op == "load":
                issued = issued_prefix[i][pc]
                buf = stores[i][drains[i]:issued]
                val = load_value(mem, instr[1], instr[2], buf)
                npcs = list(pcs)
                npcs[i] = pc + 1
                for obs, fm in f(tuple(npcs), drains, mem):
                    new_obs = list(obs)
                    new_obs[i] = (val,) + new_obs[i]
                    results.add((tuple(new_obs), fm))
            elif op == "fence":
                if drains[i] == issued_prefix[i][pc]:
                    npcs = list(pcs)
                    npcs[i] = pc + 1
                    results.update(f(tuple(npcs), drains, mem))
            elif op == "xchg":
                if drains[i] == issued_prefix[i][pc]:
                    val = load_value(mem, instr[1], instr[2], ())
                    nmem = write_bytes(mem, instr[1], instr[2], instr[3])
                    npcs = list(pcs)
                    npcs[i] = pc + 1
                    for obs, fm in f(tuple(npcs), drains, nmem):
                        new_obs = list(obs)
                        new_obs[i] = (val,) + new_obs[i]
                        results.add((tuple(new_obs), fm))

        # drain transitions
        for i in range(T):
            issued = issued_prefix[i][pcs[i]]
            if drains[i] < issued:
                s = stores[i][drains[i]]
                nmem = write_bytes(mem, s[0], s[1], s[2])
                ndrains = list(drains)
                ndrains[i] += 1
                results.update(f(pcs, tuple(ndrains), nmem))

        return frozenset(results)

    start_pcs = tuple(0 for _ in range(T))
    start_drains = tuple(0 for _ in range(T))
    outcomes = f(start_pcs, start_drains, mem0)
    out = []
    for obs, mem in outcomes:
        out.append({"reads": [list(x) for x in obs], "memory": list(mem)})
    return {"outcomes": out}


if __name__ == "__main__":
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        print(json.dumps(solve(json.loads(line))))
