from main import solve

def brute(request):
    mem0=tuple(request['memory'])
    threads=request['threads']
    T=len(threads)
    parsed=[]
    for t in threads:
        its=[]
        for x in t:
            if x[0]=='store': its.append(('store',x[1],x[2],x[3]))
            elif x[0]=='load': its.append(('load',x[1],x[2]))
            elif x[0]=='fence': its.append(('fence',))
            elif x[0]=='xchg': its.append(('xchg',x[1],x[2],x[3]))
        parsed.append(tuple(its))
    L=tuple(len(x) for x in parsed)
    def wb(mem,addr,w,val):
        m=list(mem)
        for b in range(w): m[addr+b]=(val>>(8*b))&0xFF
        return tuple(m)
    def loadv(mem,addr,w,buf):
        out=0
        for b in range(w):
            a=addr+b; byte=None
            for s in reversed(buf):
                if s[0]<=a<s[0]+s[1]:
                    byte=(s[2]>>(8*(a-s[0])))&0xFF; break
            if byte is None: byte=mem[a]
            out|=byte<<(8*b)
        return out
    start=((0,)*T, ((),)*T, mem0, ((),)*T)
    stack=[start]; seen={start}; outcomes=set()
    while stack:
        pcs,bufs,mem,obs=stack.pop()
        if all(pcs[i]==L[i] and not bufs[i] for i in range(T)):
            outcomes.add((obs,mem)); continue
        succ=[]
        for i in range(T):
            if pcs[i]<L[i]:
                instr=parsed[i][pcs[i]]; op=instr[0]
                np=list(pcs); np[i]+=1; np=tuple(np)
                if op=='store':
                    nb=list(bufs); nb[i]=nb[i]+((instr[1],instr[2],instr[3]),)
                    succ.append((np,tuple(nb),mem,obs))
                elif op=='load':
                    v=loadv(mem,instr[1],instr[2],bufs[i])
                    no=list(obs); no[i]=no[i]+(v,)
                    succ.append((np,bufs,mem,tuple(no)))
                elif op=='fence':
                    if not bufs[i]: succ.append((np,bufs,mem,obs))
                elif op=='xchg':
                    if not bufs[i]:
                        v=loadv(mem,instr[1],instr[2],())
                        nm=wb(mem,instr[1],instr[2],instr[3])
                        no=list(obs); no[i]=no[i]+(v,)
                        succ.append((np,bufs,nm,tuple(no)))
        for i in range(T):
            if bufs[i]:
                s=bufs[i][0]; nm=wb(mem,s[0],s[1],s[2])
                nb=list(bufs); nb[i]=nb[i][1:]
                succ.append((pcs,tuple(nb),nm,obs))
        for st in succ:
            if st not in seen:
                seen.add(st); stack.append(st)
    return outcomes

def gen(rng, maxins=6, maxmem=4):
    n=rng.randint(1,3)
    mem=[rng.randrange(256) for _ in range(rng.randint(1,maxmem))]
    threads=[]
    left=maxins
    for i in range(n):
        k=rng.randint(0,min(3,left))
        left-=k
        t=[]
        for _ in range(k):
            op=rng.choice(['store','load','fence','xchg'])
            w=rng.choice([1,2,4])
            # choose address with fit
            maxa=len(mem)-w
            if maxa<0: w=rng.choice([1,2]); maxa=len(mem)-w
            if maxa<0: w=1; maxa=len(mem)-w
            a=rng.randint(0,maxa)
